const e="Bipolar Disorder | Michelle Barratt Psychology",i="Bipolar Disorder therapy provides specialised support for managing mood changes, improving stability, and building long-term wellbeing.",t='<!--$--><section class="bg-gradient-to-br from-plum to-rose text-white"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20"><div><nav aria-label="Breadcrumb" class="mb-6"><ol class="flex flex-wrap items-center gap-2 text-[12px] uppercase tracking-[0.14em] text-white/75"><li><a class="hover:text-white" href="/">Home</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li><a class="hover:text-white active" href="/therapy-services" data-status="active" aria-current="page">Therapy Services</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li class="text-white" aria-current="page">Bipolar Disorder</li></ol></nav><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-white/85 mb-3">Specialised Therapy</p><h1 class="text-white text-[32px] md:text-[44px] font-semibold leading-[1.08] max-w-3xl">Bipolar Disorder Therapy</h1><div class="h-[3px] w-16 bg-sun my-5" aria-hidden="true"></div><div class="max-w-2xl text-[16px] md:text-[17px] text-white/95 space-y-3"><p>Bipolar Disorder therapy provides specialised support for managing mood changes, improving stability, and building long-term wellbeing.</p><p>Michelle Barratt Psychology Administrative Services connects clients with experienced Brisbane psychologists and online Australia-wide practitioners who provide evidence-based treatment, helping individuals recognise early warning signs, develop coping strategies, and maintain meaningful daily functioning.</p></div><div class="mt-6 flex flex-wrap gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-white text-plum hover:bg-blush " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-white/70 text-white hover:bg-white/10 " href="/practitioners">See Practitioners</a></div></div></div></section><section class="bg-soft !py-0"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="py-14 md:py-16"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2023/02/pexels-liza-summer-6382642.jpg" alt="Pexels Liza Summer 6382642" class="w-full aspect-[16/9] max-h-[520px] object-cover rounded border border-lilac"/></div></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Bipolar Disorder Therapy in Brisbane</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Bipolar Disorder care requires specialised, consistent clinical support focused on mood stabilisation, relapse prevention, and long-term functional recovery. Treatment typically combines psychoeducation, mood monitoring, structured therapy for early warning signs, and collaborative planning to reduce the frequency and impact of mood episodes. Michelle Barratt Psychology (MBP) provides in-person therapy across Brisbane, and flexible online therapy options for children, adolescents, adults, and couples Australia-wide, ensuring your healing journey remains consistent and accessible.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How does MBP support therapy for Bipolar Disorder?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt Psychology Administrative Services (MBP) provides a stable administrative foundation that connects you with experienced Brisbane psychologists and allied health professionals who specialise in bipolar disorder.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Our hub delivers reliable scheduling, professional follow-up, and discreet coordination so independent clinicians can concentrate on clinical management rather than logistics.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">That consistent framework helps practitioners manage complex mood cycles more effectively and supports continuity of care.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What does MBP do to provide professional support?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Clinically Informed Intake</h3><p class="text-[15px] leading-relaxed text-ink/85">Fast, sensitive intake that prepares you and your practitioner for focused therapy.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Sensitive, timely scheduling</h3><p class="text-[15px] leading-relaxed text-ink/85">Begin care without unnecessary delay through respectful, prioritised access.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Clear administrative boundaries</h3><p class="text-[15px] leading-relaxed text-ink/85">Protects the therapeutic relationship and preserves clinician objectivity.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Coordinated care</h3><p class="text-[15px] leading-relaxed text-ink/85">Liaison with employers and health providers when appropriate, handled with discretion.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Referral Assistance</h3><p class="text-[15px] leading-relaxed text-ink/85">Support with referrals, Medicare paperwork, and treatment-related administration.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Flexible Access</h3><p class="text-[15px] leading-relaxed text-ink/85">Brisbane-based and telehealth appointment options that support continuity of care.</p></div></div></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How do I get started?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are seeking a respectful, heard, and professionally managed pathway to Bipolar Disorder treatment, please get in touch. Email us using the form below, and we will help you find a Brisbane psychologist or allied health practitioner who specialises in borderline personality disorder and long-term recovery.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">You may also view our Practitioner Page and select the clinician of your choice:</p><h3 class="text-2xl font-semibold mt-8 mb-3">Important safety note</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are in immediate danger, experiencing severe distress, or having thoughts of harming yourself, contact emergency services or a crisis service right away. If you are concerned but not in immediate danger, please mention this when you contact us so we can prioritise an appropriate, timely response.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What Is Bipolar Disorder?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Bipolar Disorder is a mental health condition that affects a person&#x27;s mood, energy, behaviour, and ability to function. Individuals may experience periods of elevated mood, known as hypomania or mania, as well as episodes of depression. These mood states can vary in intensity and duration, affecting daily responsibilities, relationships, and overall wellbeing.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">While Bipolar Disorder is a long-term condition, many people lead fulfilling and productive lives with appropriate treatment, support, and self-management strategies.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How can Bipolar Disorder affect everyday functioning?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Mood episodes can influence many aspects of life, including decision-making, concentration, sleep, relationships, employment, finances, and physical health. During periods of elevated mood, individuals may experience increased energy, impulsivity, or reduced awareness of risks. During depressive episodes, motivation, confidence, and emotional wellbeing may significantly decline.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Recognising these patterns early can help reduce the impact of mood episodes and support more effective intervention.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Recognising early warning signs</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Identifying early warning signs can be one of the most important components of Bipolar Disorder management.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Signs of hypomania or mania may include:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Reduced need for sleep • Increased energy or activity levels • Racing thoughts • Rapid speech • Heightened confidence • Increased impulsivity • Excessive spending • Increased irritability or agitation • Taking on multiple projects simultaneously</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Signs of bipolar depression may include:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Fatigue or low energy • Increased or decreased sleep • Reduced motivation • Social withdrawal • Feelings of hopelessness • Difficulty concentrating • Loss of interest in usual activities • Changes in appetite</span></li></ul><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Early identification often allows for quicker intervention and improved symptom management.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How can therapy help?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Therapy plays an important role in helping individuals manage Bipolar Disorder alongside medical treatment where appropriate. Evidence-based psychological interventions can help individuals understand mood patterns, recognise triggers, develop coping skills, and strengthen emotional regulation.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Treatment may include Cognitive Behavioural Therapy (CBT) , Dialectical Behaviour Therapy (DBT), psychoeducation, mood monitoring, relapse prevention planning, emotional regulation strategies, and structured goal setting. Therapy can also support communication, relationships, and day-to-day functioning.</p><h3 class="text-2xl font-semibold mt-8 mb-3">Dialectical Behaviour Therapy</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">A specialised form of therapy that focuses on teaching skills to manage intense emotions, reduce self-destructive behaviours, and improve relationships. It combines mindfulness, emotional regulation, distress tolerance, and interpersonal effectiveness principles to help individuals navigate their emotional landscape more effectively.</p><h3 class="text-2xl font-semibold mt-8 mb-3">Cognitive Behaviour Therapy</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">A widely used therapy that aims to identify and change negative thought patterns and behaviours. It helps individuals understand the connection between their thoughts, feelings, and actions and develop strategies to cope with challenging emotions and situations.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Building stability and resilience</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Effective Bipolar Disorder management extends beyond responding to mood episodes. Long-term treatment often focuses on developing routines, maintaining healthy sleep patterns, managing stress, strengthening support networks, and monitoring early warning signs.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">By building awareness and developing practical strategies, individuals can reduce the frequency and impact of mood episodes while improving overall wellbeing and quality of life.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">The psychologists at Michelle Barratt Psychology are dedicated to fostering a nurturing and understanding atmosphere for our clients. Together, we strive to craft a tailored treatment strategy that caters to your individual needs and aspirations. Whether you&#x27;re new to therapy or have prior experience, we&#x27;re here to assist you on your journey toward healing and enhanced mental wellness.</p><figure class="my-9"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2026/05/38882.jpg" alt="38882" loading="lazy" class="w-full max-w-4xl aspect-[3/2] object-cover rounded border border-lilac"/></figure><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Bipolar Disorder affects more than the individual experiencing symptoms. Family members, partners, and carers can benefit from learning practical strategies that support communication, stability, emotional wellbeing, and healthy boundaries while navigating the challenges associated with mood disorders.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Supporting a Loved One Living with Bipolar Disorder</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Living with or caring for someone with Bipolar Disorder can be both rewarding and challenging. Family members often experience uncertainty when trying to understand mood changes, behavioural differences, and the impact of mood episodes on everyday life.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Education, communication, and support can play an important role in helping families navigate these challenges while maintaining healthy and supportive relationships. Understanding the condition can also help reduce conflict, confusion, and emotional strain.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Families who feel informed and supported are often better equipped to assist their loved one while maintaining their own well-being.</p><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">1 Understanding Symptoms</h3><p class="text-[15px] leading-relaxed text-ink/85">Learn how Bipolar Disorder affects mood, behaviour, energy, and decision-making so you can respond with greater understanding and confidence.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">2 Recognising Warning Signs</h3><p class="text-[15px] leading-relaxed text-ink/85">Develop awareness of early changes in mood, behaviour, or routine that may indicate an emerging mood episode.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">3 Communication Skills</h3><p class="text-[15px] leading-relaxed text-ink/85">Build healthier communication strategies that reduce conflict and encourage supportive conversations.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">4 Healthy Boundaries</h3><p class="text-[15px] leading-relaxed text-ink/85">Establish boundaries that support both your loved one&#x27;s wellbeing and your own emotional health.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">5 Crisis Planning</h3><p class="text-[15px] leading-relaxed text-ink/85">Work collaboratively to develop practical plans for managing periods of significant emotional distress or mood instability.</p></div></div></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Contact Us on the Email Form Below</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Please be advised that you&#x27;ll receive a response within 24 to 48 hours.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If in crisis, please call 000.</p></div></section><section class="bg-lilac !py-14"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-4">More in <!-- -->Specialised Therapy</p><ul class="flex flex-wrap gap-3"><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/borderline-personality-disorder">Borderline Personality Disorder<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/personality-disorders">Personality Disorders<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/narcissistic-personality-disorder">Narcissistic Personality Disorder<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/diabetes">Diabetes Mental Health Support<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/psychodynamic-therapy">Psychodynamic Therapy<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/eating-disorders">Eating Disorders<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li></ul></div></section><section class="bg-blush"><div class="mx-auto max-w-4xl px-5 py-14 md:py-16 text-center"><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-2.5">Take the first step</p><h2 class="text-[30px] md:text-[40px] font-semibold leading-[1.1]">Ready to Take the First Step?</h2><div class="h-[3px] w-14 bg-sun mt-4 mx-auto" aria-hidden="true"></div><p class="mt-5 text-[17px]">Seeking support can feel overwhelming, but you do not have to navigate life&#x27;s challenges alone. Our administration team can help answer your questions, explain appointment options and connect you with a suitable practitioner.</p><p class="mt-3">Prefer to call? Phone our administration team on <a class="text-ocean underline underline-offset-4 font-medium" href="tel:0731850040">07 3185 0040</a>.</p><div class="mt-7 flex flex-wrap justify-center gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-rose text-white hover:bg-[#9d2a59] " href="/practitioners">Book Online</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-ocean text-white hover:bg-[#095a6f] " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-plum text-plum hover:bg-lilac  active" href="/therapy-services" data-status="active" aria-current="page">Explore Services</a></div><p class="mt-5 text-sm text-ink/70">If in crisis, please call 000.</p></div></section><!--/$-->',a={title:e,description:i,html:t};export{a as default,i as description,t as html,e as title};
